/**
 * MosaicArtifactCanvasAdapter — dual-source artifact runtime chrome.
 *
 * Absorbs the 4 any-debate-ai runtime concerns (canvas-toggle, artifact-canvas,
 * artifact-renderer, artifact-toolbar) behind ONE presentation layer that
 * renders under either runtime source:
 *
 *   (a) @ai-sdk-tools/artifacts — pass `source={{ kind: "ai-sdk-artifacts", ... }}`
 *   (b) MCP Apps ui:// bridge   — pass `source={{ kind: "mcp-ui", ... }}`
 *
 * Both are normalized by `normalizeArtifact` (./normalize.ts) into one
 * `NormalizedArtifact` shape before this component ever touches them — this
 * component itself never branches on `source.kind` beyond that single call.
 *
 * i18n: zero hardcoded user-facing strings (mosaic-blocks doctrine — see
 * src/__tests__/i18n-no-hardcoded-literals.test.ts). Every label is a
 * required prop; the host owns the language.
 *
 * data-slot="artifact-canvas-adapter" on the root, "artifact-canvas-toggle"
 * on the toggle button, "artifact-canvas-toolbar" on the toolbar,
 * "artifact-canvas-body" on the rendered artifact region.
 */

import type * as React from "react";
import { normalizeArtifact } from "./normalize.js";
import type { ArtifactCanvasSource, ArtifactType } from "./types.js";

function cn(...classes: (string | undefined | null | false)[]): string {
  return classes.filter(Boolean).join(" ");
}

export interface MosaicArtifactCanvasAdapterLabels {
  /** Accessible name for the collapsed-state toggle button. */
  toggleLabel: string;
  /** Accessible name for the canvas close button. */
  closeLabel: string;
  /** Region heading shown in the toolbar when the canvas is open. */
  toolbarHeading: string;
  /** Heading shown when no artifact is active. */
  emptyTitle: string;
  /** Body copy shown when no artifact is active. */
  emptyBody: string;
  /** Heading shown when the source resolves to no renderable artifact. */
  notFoundTitle: string;
  /** Body copy shown when the source resolves to no renderable artifact. */
  notFoundBody: string;
  /** Localizes the artifact type badge, e.g. (t) => ({ document: "Document", ... })[t]. */
  typeLabel: (type: ArtifactType) => string;
}

export interface MosaicArtifactCanvasAdapterProps {
  /** Either runtime source; `null` renders the empty state. */
  source: ArtifactCanvasSource | null;
  isOpen: boolean;
  onToggle: () => void;
  onClose: () => void;
  labels: MosaicArtifactCanvasAdapterLabels;
  className?: string;
  ref?: React.Ref<HTMLDivElement>;
}

export function MosaicArtifactCanvasAdapter({
  source,
  isOpen,
  onToggle,
  onClose,
  labels,
  className,
  ref,
}: MosaicArtifactCanvasAdapterProps) {
  const artifact = source ? normalizeArtifact(source) : null;

  return (
    <div ref={ref} data-slot="artifact-canvas-adapter" className={cn("relative", className)}>
      <button
        type="button"
        data-slot="artifact-canvas-toggle"
        aria-label={labels.toggleLabel}
        aria-expanded={isOpen}
        onClick={onToggle}
        className={cn(
          "inline-flex items-center justify-center rounded-md px-3 py-1.5 text-sm font-medium",
          "outline-none transition-colors",
          "focus-visible:ring-ring focus-visible:ring-[3px]",
          "bg-muted text-muted-foreground hover:text-foreground",
        )}
      >
        {labels.toggleLabel}
      </button>

      {isOpen && (
        <section
          aria-label={labels.toolbarHeading}
          data-slot="artifact-canvas"
          className={cn(
            "mt-2 flex flex-col rounded-lg border border-border bg-background",
            "shadow-xs",
          )}
        >
          <div
            data-slot="artifact-canvas-toolbar"
            className="flex items-center justify-between border-border border-b px-4 py-2"
          >
            <span className="font-medium text-sm">{labels.toolbarHeading}</span>
            <button
              type="button"
              aria-label={labels.closeLabel}
              onClick={onClose}
              className={cn(
                "rounded-md p-1 outline-none transition-colors",
                "focus-visible:ring-ring focus-visible:ring-[3px]",
                "hover:bg-muted",
              )}
            >
              {labels.closeLabel}
            </button>
          </div>

          <div data-slot="artifact-canvas-body" className="flex-1 p-4">
            {!source && (
              <div className="text-center">
                <p className="font-medium text-muted-foreground">{labels.emptyTitle}</p>
                <p className="mt-1 text-muted-foreground/70 text-sm">{labels.emptyBody}</p>
              </div>
            )}

            {source && !artifact && (
              <div className="text-center">
                <p className="font-medium text-muted-foreground">{labels.notFoundTitle}</p>
                <p className="mt-1 text-muted-foreground/70 text-sm">{labels.notFoundBody}</p>
              </div>
            )}

            {artifact && (
              <div data-slot="artifact-canvas-artifact" data-artifact-type={artifact.type}>
                <div className="flex items-center gap-2">
                  <span
                    data-slot="artifact-canvas-type-badge"
                    className="rounded-full bg-secondary px-2 py-0.5 text-secondary-foreground text-xs"
                  >
                    {labels.typeLabel(artifact.type)}
                  </span>
                  <h3 className="font-semibold text-base">{artifact.title}</h3>
                </div>
              </div>
            )}
          </div>
        </section>
      )}
    </div>
  );
}

MosaicArtifactCanvasAdapter.displayName = "MosaicArtifactCanvasAdapter";

import type {
  AiSdkArtifactsSource,
  ArtifactCanvasSource,
  ArtifactType,
  McpUiSource,
  NormalizedArtifact,
} from "./types.js";

const KNOWN_TYPES: readonly ArtifactType[] = ["document", "data-table", "checklist", "chart"];

function isArtifactType(value: string): value is ArtifactType {
  return (KNOWN_TYPES as readonly string[]).includes(value);
}

function titleFromData(data: Record<string, unknown>): string {
  return typeof data.title === "string" ? data.title : "";
}

/** Source (a): @ai-sdk-tools/artifacts `useArtifacts()` shape. */
export function normalizeFromAiSdkArtifacts(
  source: AiSdkArtifactsSource,
): NormalizedArtifact | null {
  if (!source.activeId) return null;
  const entry = source.artifacts.find((a) => a.id === source.activeId);
  if (!entry) return null;
  if (!isArtifactType(entry.type)) return null;
  return {
    id: entry.id,
    type: entry.type,
    title: titleFromData(entry.data),
    data: entry.data,
  };
}

/**
 * Source (b): MCP Apps ui:// bridge. Requires the GA-nested key
 * `_meta.ui.resourceUri` (matches mcp-doctor D6 `present`/conforming state).
 * The artifact type is the last path segment of the resourceUri
 * (`ui://artifact-canvas/document` -> "document"); `structuredContent` is
 * the artifact payload, same shape family as the ai-sdk-artifacts entry.
 */
export function normalizeFromMcpToolResult(source: McpUiSource): NormalizedArtifact | null {
  const resourceUri = source.toolResult?._meta?.ui?.resourceUri;
  if (!resourceUri) return null;

  const segments = resourceUri.split("/").filter(Boolean);
  const typeSegment = segments[segments.length - 1];
  if (!typeSegment || !isArtifactType(typeSegment)) return null;

  const data = source.toolResult.structuredContent ?? {};
  const id = typeof data.id === "string" ? data.id : resourceUri;

  return {
    id,
    type: typeSegment,
    title: titleFromData(data),
    data,
  };
}

/** Single entry point: dispatches to the right normalizer by `source.kind`. */
export function normalizeArtifact(source: ArtifactCanvasSource): NormalizedArtifact | null {
  if (source.kind === "ai-sdk-artifacts") return normalizeFromAiSdkArtifacts(source);
  if (source.kind === "mcp-ui") return normalizeFromMcpToolResult(source);
  return null;
}

/**
 * artifact-canvas-adapter — dual-source contract.
 *
 * The adapter normalizes an artifact from EITHER runtime source into one
 * internal shape (`NormalizedArtifact`) so a single presentation layer
 * renders under both:
 *
 *   (a) @ai-sdk-tools/artifacts  — `useArtifacts()` client shape
 *   (b) MCP Apps ui:// bridge    — GA nested `_meta.ui.resourceUri` tool result
 *
 * Never widen this file to a third shape without adding its own
 * `normalizeFrom*` function and a dedicated integration test proving the
 * new source traverses the adapter at runtime — see D6 (mcp-doctor) for the
 * static form-check this shape must keep satisfying.
 */

export type ArtifactType = "document" | "data-table" | "checklist" | "chart";

export interface NormalizedArtifact {
  id: string;
  type: ArtifactType;
  title: string;
  /** Raw source-specific payload, kept for the type-specific renderer. */
  data: Record<string, unknown>;
}

// ── (a) @ai-sdk-tools/artifacts source shape ──────────────────────────────────

export interface AiSdkArtifactEntry {
  id: string;
  type: string;
  data: Record<string, unknown>;
}

export interface AiSdkArtifactsSource {
  kind: "ai-sdk-artifacts";
  artifacts: AiSdkArtifactEntry[];
  activeId: string | null;
}

// ── (b) MCP Apps ui:// bridge source shape ────────────────────────────────────

/**
 * The GA-nested MCP Apps UI key, exactly the form D6 (mcp-doctor) classifies
 * as `present`/conforming: `_meta: { ui: { resourceUri } }`. Community
 * (`io.modelcontextprotocol/ui`) and flat (`ui/resourceUri`) forms are
 * rejected by the normalizer — see `normalizeFromMcpToolResult`.
 */
export interface McpToolResultMeta {
  ui: { resourceUri: string };
}

// Inlined on one line (not the `McpToolResultMeta` alias) so the literal
// GA-nested shape `_meta: { ui: ...}` is present verbatim in production
// source — this is what mcp-doctor's D6 detector classifies as
// `present`/conforming, distinct from the community and flat deprecated
// forms it rejects.
export interface McpToolResult {
  structuredContent: Record<string, unknown>;
  _meta: { ui: { resourceUri: string } };
}

export interface McpUiSource {
  kind: "mcp-ui";
  toolResult: McpToolResult;
}

export type ArtifactCanvasSource = AiSdkArtifactsSource | McpUiSource;
